#!/usr/bin/env python3
"""Build a JSON file of 200 new scholarship candidates from web search results."""
import json
from datetime import datetime, timezone

TODAY = datetime.now(timezone.utc).strftime("%Y-%m-%d")
SOURCES_USED = set()

def s(source, source_id, name, org, cat, edu, field, amt_min, amt_max, display, 
      deadline, app_url, desc="", elig="", state="", citizenship="None", 
      residency="International", org_type="", gender="", form_url=None):
    return {
        "source": source,
        "source_id": source_id,
        "scholarship_name": name,
        "organization": org,
        "organization_type": org_type,
        "description": desc,
        "eligibility": elig,
        "amount_min": amt_min,
        "amount_max": amt_max,
        "amount_display": display,
        "deadline": deadline,
        "application_url": app_url,
        "form_url": form_url or app_url,
        "category": cat,
        "education_level": edu,
        "field_of_study": field,
        "state_restriction": state,
        "gpa_min": None,
        "citizenship": citizenship,
        "ethnicity": "",
        "gender": gender,
        "military_affiliation": "",
        "residency_requirement": residency,
    }

records = []
i = 0
def add(rec):
    global i
    i += 1
    rec["source_id"] = rec["source_id"].replace("{seq}", f"{i:03d}")
    records.append(rec)

