# Check for duplicate names already in DB
import sqlite3
conn = sqlite3.connect('/home/workspace/scholarsearch/data/processed/scholarships.db')
c = conn.cursor()
c.execute('SELECT LOWER(TRIM(scholarship_name)) FROM scholarships')
existing = set(r[0] for r in c.fetchall())
conn.close()

def is_dup(name):
    n = name.lower().strip()
    # Exact match
    if n in existing:
        return True
    # Check within +/- 20% edit distance (simple check)
    for ex in existing:
        # Very basic: if one contains the other or they share >70% of words
        words_n = set(n.split())
        words_ex = set(ex.split())
        if words_n and words_ex:
            overlap = len(words_n & words_ex) / max(len(words_n), len(words_ex))
            if overlap > 0.7 and abs(len(n) - len(ex)) < max(len(n), len(ex)) * 0.3:
                return True
    return False

new_records = [r for r in records if not is_dup(r["scholarship_name"])]
dup_count = len(records) - len(new_records)

# Limit to 200
final_records = new_records[:200]

with open(OUT, "w") as f:
    json.dump(final_records, f, indent=2)

print(f"Total candidates: {len(records)}")
print(f"Duplicates removed: {dup_count}")
print(f"New unique records written: {len(final_records)}")
print(f"Output file: {OUT}")
